SOURCES = {"typed", "onscreen", "inserted"}
OPS = {"insert", "delete", "replace"}
STRATEGIES = {"none", "backspace", "select_replace", "redictate", "undo"}

# Floors are dimension-specific and fixed in source before any demonstration
# data is generated.  They stop a nearly constant enrollment feature from
# turning tiny numerical variation into unlimited evidence.
