```python
#!/usr/bin/env python3
# stepcheck.py v2 -- price the truth of a standing self-description line.
# FIX-1 COVERAGE: nonempty register -> zero parsed Step lines == REFUSE.
# FIX-2 MARKER: --marker needs a DATED, reasoned attestation line, not a substring.
import sys, os, re, datetime

DATE = re.compile(r'(\d{4}-\d{2}-\d{2})')
STEP = re.compile(r'^\s*(?:step|task)\s*:\s*(.+?)\s*$', re.I)
FLD  = re.compile(r'(check|expect|verified|expires)\s*:\s*([^|]+?)\s*(?=\||$)', re.I)
MARKER = re.compile(r'^\s*intentionally\s+empty\s+(\d{4}-\d{2}-\d{2})\s+reason\s*=\s*(\S.*?)\s*$', re.I | re.M)

def day(s):
    m = DATE.search(s or "")
    if not m: return None
    try: return datetime.date.fromisoformat(m.group(1))
    except ValueError: return None

def steps(text):
    out, cur = [], None
    for ln in text.splitlines():
        m = STEP.match(ln)
        if m:
            if cur: out.append(cur)
            cur = {"text": m.group(1), "check": None, "expect": None, "verified": None, "expires": None}
        if cur is None: continue
        for k, v in FLD.findall(ln): cur[k.lower()] = v.strip()
    if cur: out.append(cur)
    return out

def price(s, today):
    e, v = day(s.get("expires")), day(s.get("verified"))
    if e is None:  return "decayed", "no expires: date (prose with a date-shaped hole)"
    if v is None:  return "decayed", "expires: with no verified: date"
    if e < today:  return "stale", "expires %s < today %s -> self-demotes to UNVERIFIED" % (e, today)
    if not (s.get("check") and s.get("expect")): return "decayed", "not re-runnable: needs check: AND expect:"
    return "ok", "verified %s, expires %s" % (v, e)

def canned(s):
    h = s["text"].split("|")[0].strip()
    m = re.search(r'waiting\s+on\s+(.+)$', h, re.I)
    t = (m.group(1).strip().rstrip(".") if m else None)
    return ("You wrote: waiting on %s. Show me %s's last event, or amend the line." % (t, t)) if t else ('You wrote: "%s". Show me the artifact it names, dated, or amend.' % h)

def valid_marker(path, today):
    if not path or not os.path.exists(path): return False, "marker file absent"
    txt = open(path, "r", encoding="utf-8", errors="replace").read()
    m = MARKER.search(txt)
    if not m: return False, "no 'intentionally empty <date> reason=<text>' attestation line"
    md = day(m.group(1))
    if md is None: return False, "marker date unparseable"
    if md > today: return False, "marker dated in the future (%s)" % md
    return True, "marker %s reason=%r" % (md, m.group(2)[:60])

def main(a):
    if len(a) < 2:
        print("usage: stepcheck.py <register> [--marker F] [--today YYYY-MM-DD] [--expect N]"); return 1
    reg, marker, today, expect = a[1], None, datetime.date.today(), None
    i = 2
    while i < len(a):
        if a[i] == "--marker" and i+1 < len(a): marker, i = a[i+1], i+2
        elif a[i] == "--today" and i+1 < len(a): today, i = (day(a[i+1]) or today), i+2
        elif a[i] == "--expect" and i+1 < len(a):
            try: expect = int(a[i+1])
            except ValueError: print("bad --expect:", a[i+1]); return 1
            i += 2
        else: print("unknown arg:", a[i]); return 1
    verdict, wiped, why = "OK", "PRESENT", ""
    parsed = []
    if not os.path.exists(reg):
        wiped, verdict, why = "ABSENT", "REFUSE", "register does not exist -- destruction or a moved path, not tidiness"
    else:
        t = open(reg, "r", encoding="utf-8", errors="replace").read()
        if not t.strip():
            ok, detail = valid_marker(marker, today)
            wiped = "EMPTY-CLEARED" if ok else "ZERO-BYTES"
            if not ok:
                verdict = "REFUSE"; why = "empty and marker INVALID (%s) -- 0 under budget is destruction read as success" % detail
            else:
                why = "empty, cleared by %s" % detail
        else:
            parsed = steps(t)
            if not parsed:   # FIX-1
                verdict = "REFUSE"
                why = "nonempty register parsed to ZERO Step lines -- unrecognized format; a zero-length parse is not a clean parse (coverage failure)"
    print("stepcheck v2  register=%s  today=%s" % (reg, today))
    print("WIPED  : %s" % wiped)
    if why: print("         %s" % why)
    if parsed:
        if expect is not None and len(parsed) != expect:
            verdict = "REFUSE"
            print("COVERAGE: parsed %d != expected %d -- REFUSE (membership not established)" % (len(parsed), expect))
        for s in parsed:
            st, rs = price(s, today)
            print("  [%-7s] %s\n             -> %s" % (st.upper(), s["text"], rs))
            if st != "ok":
                print("             re-run: %s   expect: %s" % (s.get("check") or "-", s.get("expect") or "-"))
                print("             2nd SEAT ASKS: %s" % canned(s))
                verdict = "REFUSE"
    print("VERDICT: %s" % verdict)
    return 0 if verdict == "OK" else 2

if __name__ == "__main__":
    sys.exit(main(sys.argv))
```

