Synthetic benchmark only. This is not an authentication/security product.
No event capture, networking, biometric upload or automatic account actions.
"""
import argparse
import hashlib
import json
import math
import random
import statistics as st
from pathlib import Path

VERSION = 'marrow-research-2'
FEATURE_NAMES = ('path_excess', 'speed_cv', 'turn', 'click_pause_ratio',
                 'text_gap_cv', 'correction_fraction', 'correction_gap_ratio')
FLOORS = (.015, .06, .025, .04, .08, .025, .10)
MODES = ('typed', 'on_screen', 'inserted')


def dump(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, sort_keys=True)+'\n')


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def quantile(xs, p):
    ys = sorted(xs)
    if not ys:
        raise ValueError('empty quantile')
    return ys[min(len(ys)-1, max(0, math.ceil(p*len(ys))-1))]


def cv(xs):
    return st.pstdev(xs)/max(st.mean(xs), 1e-9) if len(xs)>1 else 0.


def number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


def read_events(path):
    events = []
    header = False
    last = -1.
    for line_no, raw in enumerate(Path(path).read_text().splitlines(), 1):
        if not raw.strip():
            continue
        e = json.loads(raw)
        if not isinstance(e, dict):
            raise ValueError(f'{path}:{line_no}: object required')
        if e.get('type') == 'session':
            if events or line_no != 1 or e.get('schema') != 'marrow.v1':
                raise ValueError('one schema header required at line 1')
            header = True
            continue
        if not header:
            raise ValueError('marrow.v1 session header required')
        t = e.get('t_ms')
        if not number(t) or t < 0 or t < last:
            raise ValueError(f'{path}:{line_no}: finite monotonic nonnegative t_ms required')
        last = t
        kind = e.get('type')
        if kind in ('move', 'click'):
            if any(not number(e.get(k)) or not 0 <= e[k] <= 1 for k in ('x','y')):
                raise ValueError('normalized x,y in [0,1] required')
            if kind == 'click' and e.get('button') not in ('primary','secondary','other'):
                raise ValueError('click button required')
        elif kind == 'text':
            if e.get('mode') not in MODES:
                raise ValueError('typed/on_screen/inserted mode required')
            if not isinstance(e.get('insert'), str) or not isinstance(e.get('delete'), int) or isinstance(e['delete'],bool) or e['delete']<0:
                raise ValueError('text insert string and nonnegative delete integer required')
            if not e['insert'] and not e['delete']:
                raise ValueError('empty text edit')
        else:
            raise ValueError('unknown event type')
        events.append(e)
    if not events:
        raise ValueError('no events')
    return events


def features(events):
    # Closed-click strokes, without dependence on OS, identity, screen size,
    # text contents, source mode or filename. Ratios reduce uniform speed drift.
    strokes=[]; stroke=[]; text=[]
    for e in events:
        if e['type']=='move':
            stroke.append(e)
        elif e['type']=='click':
            if len(stroke)>=5:
                strokes.append((stroke,e))
            stroke=[]
        elif e['type']=='text':
            text.append(e)
    if len(strokes)<8 or len(text)<20:
        raise ValueError('insufficient evidence: need 8 strokes with >=5 moves and 20 text edits')
    excess=[]; speed_variation=[]; turns=[]; pauses=[]
    for moves, click in strokes:
        delta=[(b['x']-a['x'],b['y']-a['y'],b['t_ms']-a['t_ms']) for a,b in zip(moves,moves[1:])]
        distances=[math.hypot(x,y) for x,y,_ in delta]
        chord=math.hypot(moves[-1]['x']-moves[0]['x'],moves[-1]['y']-moves[0]['y'])
        duration=moves[-1]['t_ms']-moves[0]['t_ms']
        if chord<.01 or duration<=0:
            continue
        excess.append(sum(distances)/chord-1)
        speed_variation.append(cv([dist/dt for dist,(_,_,dt) in zip(distances,delta) if dt>0]))
        for (x,y,_),(u,v,_) in zip(delta,delta[1:]):
            if math.hypot(x,y)*math.hypot(u,v)>1e-12:
                turns.append(abs(math.atan2(x*v-y*u,x*u+y*v)))
        pauses.append(max(0,click['t_ms']-moves[-1]['t_ms'])/duration)
    if len(excess)<8 or not turns:
        raise ValueError('insufficient nondegenerate strokes')
    gaps=[b['t_ms']-a['t_ms'] for a,b in zip(text,text[1:]) if b['t_ms']>a['t_ms']]
    inserts=[len(e['insert']) for e in text if e['insert']]
    edits=[b['t_ms']-a['t_ms'] for a,b in zip(text,text[1:]) if b['delete'] and b['t_ms']>a['t_ms']]
    if len(gaps)<10 or not inserts:
