"""Independent contract, anti-leakage and robustness checks; stdlib only."""
import copy
import json
import math
import tempfile
import unittest
from pathlib import Path
import marrow as m


class ContractTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.tmp=tempfile.TemporaryDirectory()
        cls.root=Path(cls.tmp.name)
        cls.path=cls.root/'fixture.jsonl'
        m.synthetic(cls.path,0,'typed',98320)
        cls.events=m.read_events(cls.path)
        cls.vector=m.features(cls.events)

    @classmethod
    def tearDownClass(cls):cls.tmp.cleanup()

    def test_time_translation_and_scale(self):
        events=copy.deepcopy(self.events)
        for e in events:e['t_ms']=e['t_ms']*2+123456
        for a,b in zip(self.vector,m.features(events)):self.assertAlmostEqual(a,b,places=8)

    def test_text_content_and_mode_not_identity(self):
        events=copy.deepcopy(self.events)
        for e in events:
            if e['type']=='text':
                e['insert']='q'*len(e['insert']);e['mode']='on_screen'
            e['subject']='wrong-person';e['role']='stranger'
        self.assertEqual(self.vector,m.features(events))

    def test_bad_records(self):
        header={'type':'session','schema':'marrow.v1'}
        valid={'type':'move','t_ms':0,'x':.5,'y':.5}
        cases=[
            [valid],
            [header,{**valid,'x':float('nan')}],
            [header,{**valid,'x':1.01}],
            [header,{**valid,'t_ms':float('inf')}],
            [header,{**valid,'t_ms':2},valid],
            [header,{'type':'text','t_ms':0,'mode':'unknown','insert':'a','delete':0}],
            [header,{'type':'text','t_ms':0,'mode':'typed','insert':'','delete':0}],
            [header,{'type':'text','t_ms':0,'mode':'typed','insert':'a','delete':-1}],
            [header,{**valid,'type':'click'}],
        ]
        for i,rows in enumerate(cases):
            p=self.root/f'bad-{i}.jsonl';p.write_text('\n'.join(map(json.dumps,rows)))
            with self.subTest(i=i),self.assertRaises(ValueError):m.read_events(p)

    def test_sparse_abstains(self):
        with self.assertRaises(ValueError):m.features(self.events[:3])

    def test_duplicate_fit_rejected(self):
        with self.assertRaises(ValueError):m.fit([self.path]*5,[self.path]*5,self.root/'bad-model.json')

    def test_fit_is_reproducible_and_no_test_inputs(self):
        paths=[]
        for i in range(10):
            p=self.root/f'enroll-{i}.jsonl';m.synthetic(p,0,'inserted',70000+i);paths.append(p)
        one=m.fit(paths[:5],paths[5:],self.root/'one.json')
        two=m.fit(paths[:5],paths[5:],self.root/'two.json')
        self.assertEqual(one,two)
        manifest=[{'path':str(paths[0]),'role':'owner'}]
        with self.assertRaises(ValueError):m.evaluate(one,manifest,self.root)

    def test_wilson_known_bounds(self):
        self.assertAlmostEqual(m.interval(0,40)[1],.08762160119728664)
        self.assertEqual(m.interval(0,0),None)
        low,high=m.interval(20,40);self.assertLess(low,.5);self.assertGreater(high,.5)

    def test_incompatible_and_invalid_models_abstain(self):
        base={'version':m.VERSION,'features':m.FEATURE_NAMES,'center':[0.]*7,'scale':[1.]*7,'threshold':1.}
        variants=[{**base,'version':'marrow-research-1'}, {**base,'center':[0.]*8},
                  {**base,'scale':[0.]*7}, {**base,'threshold':float('nan')},
                  {**base,'features':['wrong']*7}]
        for model in variants:
            with self.subTest(model=model):self.assertEqual(m.score(model,self.path)['decision'],'abstain')

    def test_all_supported_modes_parse(self):
        for style in m.MODES:
            p=self.root/f'{style}.jsonl';m.synthetic(p,3,style,4141)
            self.assertEqual(len(m.features(m.read_events(p))),len(m.FEATURE_NAMES))


if __name__=='__main__':unittest.main()
```

